  function art(course){return `<div class="course-art"><img src="assets/${course.image}.svg" alt="Illustration zum Kursbereich ${esc(course.category)}" loading="lazy"><span class="pill pill-white badge-on-art">${esc(course.tag)}</span><button class="heart-on-art ${state.favorites.includes(course.id)?'is-saved':''}" data-action="favorite" data-id="${course.id}" aria-label="${state.favorites.includes(course.id)?'Kurs aus Merkliste entfernen':'Kurs zur Merkliste hinzufügen'}" aria-pressed="${state.favorites.includes(course.id)}">${icon('heart')}</button></div>`}
